// "Đủ điều kiện" (FR-21, đề xuất tầng truy vấn): APPROVED, chưa lưu trữ, không thuộc bài thi CHƯA công bố (DRAFT / SCHEDULED / OPEN / CLOSED chưa PUBLISHED).
func (q *Queries) PracticePool(ctx context.Context, arg PracticePoolParams) ([]PracticePoolRow, error) {
	rows, err := q.db.Query(ctx, practicePool, arg.CourseID, arg.Types, arg.Topic)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PracticePoolRow{}
	for rows.Next() {
		var i PracticePoolRow
		if err := rows.Scan(&i.ID, &i.Topic, &i.Difficulty); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

