const practiceSignals = `-- name: PracticeSignals :many
select (i.question ->> 'topic')::text as topic, count(*)::int as wrong_answers, count(distinct t.student_id)::int as students_affected,
       (array_agg(distinct i.question_id))[1:3]::uuid[] as sample_question_ids
from practice_answers a
join practice_items i on i.course_id = a.course_id and i.id = a.item_id
join practice_attempts t on t.course_id = a.course_id and t.id = a.attempt_id
where a.course_id = $1 and a.is_correct = false and a.answered_at >= $2 and a.answered_at < $3
group by 1
having count(distinct t.student_id) >= $4::int
order by wrong_answers desc, topic
`

type PracticeSignalsParams struct {
	CourseID    uuid.UUID
	FromAt      time.Time
	ToAt        time.Time
	MinStudents int32
}

type PracticeSignalsRow struct {
	Topic             string
	WrongAnswers      int32
	StudentsAffected  int32
	SampleQuestionIds []uuid.UUID
}

// Tín hiệu tổng hợp cho giảng viên (P10): theo chủ đề, KHÔNG định danh; chủ đề < k sinh viên bị loại ngay trong truy vấn (k-ẩn danh).
func (q *Queries) PracticeSignals(ctx context.Context, arg PracticeSignalsParams) ([]PracticeSignalsRow, error) {
	rows, err := q.db.Query(ctx, practiceSignals,
		arg.CourseID,
		arg.FromAt,
		arg.ToAt,
		arg.MinStudents,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PracticeSignalsRow{}
	for rows.Next() {
		var i PracticeSignalsRow
		if err := rows.Scan(
			&i.Topic,
			&i.WrongAnswers,
			&i.StudentsAffected,
			&i.SampleQuestionIds,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

